import { memo, useRef } from "react";
import clsx from "clsx";
import { Button, Chevron, LinkList, Popover, useDisclosure, useStableId } from "../ui/primitives.jsx";
import { GroupProvider, HeadingLevel, useStage } from "../contexts.jsx";
import { Teaser } from "../teasers/layouts.jsx";
import { interactionTracking } from "../../lib/tracking.js";
import { Anchor, Box, Item } from "../ui/ds.jsx";

export function StageSection({ stage, className, children, label }) {
    return (
        <section className={clsx("relative scroll-mt-(--header-height) border-t-4 border-brand-600 pt-3", className)} data-stage={stage.layout} data-stage-index={stage.index} aria-label={label}>
            <HeadingLevel level={2}>{children}</HeadingLevel>
        </section>
    );
}

export function StageHeader({ header, children }) {
    if (!header?.title && !children)
        return null;
    return (
        <header className="mb-4 flex flex-wrap items-center gap-x-5 gap-y-2">
            {header?.title ? <StageTitle title={header.title} /> : null}
            {header?.quickLinks?.length ? <QuickLinks links={header.quickLinks} /> : null}
            {header?.areas?.length ? <TopicMenu header={header} /> : null}
            {children}
        </header>
    );
}

function StageTitle({ title }) {
    return (
        <h2 className="text-head-m font-bold tracking-tight text-ink-900 uppercase dark:text-ink-50">
            <Anchor href={title.href} className="hover:text-brand-600">{title.label}</Anchor>
        </h2>
    );
}

function QuickLinks({ links }) {
    return (
        <ul className="flex flex-wrap gap-2">
            {links.map((link) => (
                <Item key={link.href}>
                    <Anchor href={link.href} className="rounded-chip bg-ink-100 px-2.5 py-1 text-xs font-medium text-ink-700 transition-colors hover:bg-brand-50 hover:text-brand-700 dark:bg-ink-800 dark:text-ink-200">{link.label}</Anchor>
                </Item>
            ))}
        </ul>
    );
}

// "Mehr Themen": a popover with the section's areas and top topics.
export function TopicMenu({ header }) {
    const stage = useStage();
    const anchorRef = useRef(null);
    const { open, toggle, close } = useDisclosure();
    const id = useStableId("topics");
    return (
        <Box className="ml-auto">
            <Button ref={anchorRef} variant="outline" aria-expanded={open} aria-controls={open ? id : undefined} aria-label={`Mehr Themen: ${header.title.label}`} onClick={toggle} {...interactionTracking("topic-menu", stage?.trackingName)}>
                Mehr Themen
                <Chevron open={open} />
            </Button>
            <Popover anchorRef={anchorRef} open={open} onClose={close} labelledBy={`${id}-title`} align="end" className="w-[34rem]">
                <Box id={id} className="grid grid-cols-2 gap-6">
                    <Box>
                        <h3 id={`${id}-title`} className="mb-2 text-xs font-bold text-ink-500 uppercase">Bereiche</h3>
                        <LinkList links={header.areas} />
                    </Box>
                    <Box>
                        <h3 className="mb-2 text-xs font-bold text-ink-500 uppercase">Top-Themen</h3>
                        <LinkList links={header.topTopics} className="grid grid-cols-1 gap-1.5" />
                    </Box>
                </Box>
            </Popover>
        </Box>
    );
}

export function CompanionGroup({ group }) {
    const isList = group.layout === "headline";
    return (
        <GroupProvider group={group}>
            <Box className="rounded-teaser bg-paper-muted p-4 dark:bg-paper-raised" data-group={group.layout}>
                <GroupTitle title={group.header.title} />
                {isList ? (
                    <ol className="flex flex-col">
                        {group.stream.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
                    </ol>
                ) : (
                    <Box className={clsx(group.layout === "portrait" ? "grid grid-cols-2 gap-4" : "flex flex-col divide-y divide-ink-200 dark:divide-ink-700")}>
                        {group.stream.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
                    </Box>
                )}
                <GroupFooter links={group.footerReferences} />
            </Box>
        </GroupProvider>
    );
}

function GroupTitle({ title }) {
    return (
        <h3 className="mb-2 flex items-center gap-2 text-sm font-bold text-ink-900 uppercase before:h-4 before:w-1 before:rounded-sm before:bg-signal-500 before:content-[''] dark:text-ink-50">
            <Anchor href={title.href} className="hover:text-brand-600">{title.label}</Anchor>
        </h3>
    );
}

function GroupFooter({ links }) {
    if (!links?.length)
        return null;
    return (
        <Box className="mt-3 border-t border-ink-200 pt-2 dark:border-ink-700">
            {links.map((link) => (
                <Anchor key={link.href} href={link.href} className="text-sm font-medium text-brand-600 hover:underline">{link.label} ›</Anchor>
            ))}
        </Box>
    );
}

// A widget fragment from another team. The build fills the wrapper with the
// fragment's markup (stylesheet, custom element with its data and server
// render, scripts), which React leaves alone when it hydrates.
export const EsiFragment = memo(function EsiFragment({ tag }) {
    return <div className="esi-fragment min-h-24" data-esi={tag} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: "" }} />;
});

// Ad slots are filled by the ad scripts, possibly before hydration, so React
// must not hydrate their children.
const OPAQUE = { __html: "" };

export const CommercialSlot = memo(function CommercialSlot({ name, sizes, lazy = false, minHeight, className }) {
    return (
        <div className={clsx("commercial-slot relative mx-auto flex items-center justify-center bg-ink-50 dark:bg-ink-900", className)} style={{ minHeight }} id={`slot-${name}`} data-commercial-slot={name} data-commercial-sizes={sizes} data-commercial-lazy={lazy ? "true" : "false"} suppressHydrationWarning dangerouslySetInnerHTML={OPAQUE} />
    );
});
