import { memo, useMemo } from "react";
import clsx from "clsx";
import { Badge, Picture, Timestamp } from "../ui/primitives.jsx";
import { Icon } from "../ui/icons.jsx";
import { formatCount } from "../../lib/format.js";
import { useHeadingLevel, useStage } from "../contexts.jsx";
import { teaserTracking } from "../../lib/tracking.js";
import { Anchor, Box, Paragraph, Text } from "../ui/ds.jsx";

// Static class lists, composed once at module scope like the reference's
// design system does.
const TEASER_BASE = clsx("group/teaser relative isolate flex", "transition-colors");
const HEADLINE_BASE = clsx("font-bold text-ink-900 transition-colors group-hover/teaser:text-brand-700 dark:text-ink-50", "text-balance");
const LINK_BASE = clsx("before:absolute before:inset-0 before:z-(--z-teaser-stretched-link) before:content-['']", "focus-visible:outline-none focus-visible:before:outline-2 focus-visible:before:outline-brand-500");

export function TeaserFrame({ teaser, className, children, as: Tag = "article" }) {
    const stage = useStage();
    const tracking = useMemo(() => teaserTracking(teaser, stage), [teaser, stage]);
    return (
        <Tag className={clsx(TEASER_BASE, className)} data-testid={`teaser-${teaser.layout}`} {...tracking}>
            {children}
        </Tag>
    );
}

export const TopLine = memo(function TopLine({ teaser, className }) {
    return (
        <Text className={clsx("mb-0.5 block text-sm font-medium text-brand-600 dark:text-brand-300", className)}>
            {teaser.genreLabel ? <GenreLabel label={teaser.genreLabel} /> : null}
            {teaser.topLine}
        </Text>
    );
});

function GenreLabel({ label }) {
    return <Text className="mr-1.5 font-bold text-signal-700 uppercase after:ml-1.5 after:text-ink-300 after:content-['|']">{label}</Text>;
}

export function TeaserLink({ teaser, children, className }) {
    return (
        <Anchor href={teaser.path.href} className={clsx(LINK_BASE, className)}>
            {children}
        </Anchor>
    );
}

export function Headline({ teaser, size = "s", clamp, withTopLine = true, className }) {
    const level = useHeadingLevel();
    const Tag = `h${Math.min(6, level + 1)}`;
    return (
        <Tag className={clsx(
            HEADLINE_BASE,
            size === "xs" && "text-sm leading-snug",
            size === "s" && "text-head-s",
            size === "m" && "text-head-m",
            size === "l" && "text-head-l",
            size === "xl" && "text-head-xl font-serif",
            clamp === 2 && "line-clamp-2",
            clamp === 3 && "line-clamp-3",
            clamp === 4 && "line-clamp-4",
            className,
        )}>
            <TeaserLink teaser={teaser}>
                {withTopLine ? <TopLine teaser={teaser} /> : null}
                <Text>{teaser.headline}</Text>
            </TeaserLink>
        </Tag>
    );
}

export function TeaserText({ teaser, clamp = 3, className }) {
    if (!teaser.teaserText)
        return null;
    return <Paragraph className={clsx("mt-1.5 text-[0.9375rem] leading-relaxed text-ink-700 dark:text-ink-200", clamp === 2 ? "line-clamp-2" : "line-clamp-3", className)}>{teaser.teaserText}</Paragraph>;
}

export function Byline({ teaser, className }) {
    if (!teaser.authors?.length)
        return null;
    return (
        <Text className={clsx("text-xs text-ink-500", className)}>
            Von {teaser.authors.map((author, i) => (
                <AuthorName key={i} author={author} last={i === teaser.authors.length - 1} />
            ))}
        </Text>
    );
}

function AuthorName({ author, last }) {
    return (
        <Text>
            {author.degree}{author.name}{last ? "" : ", "}
        </Text>
    );
}

export function TeaserMeta({ teaser, showTime = true, className }) {
    return (
        <Box className={clsx("relative z-(--z-teaser-actions) mt-2 flex flex-wrap items-center gap-x-3 gap-y-1", className)}>
            <TeaserFlags teaser={teaser} />
            {showTime ? <Timestamp value={teaser.published} /> : null}
            <Byline teaser={teaser} />
            <CommentCount count={teaser.commentCount} href={teaser.path.href} />
        </Box>
    );
}

export function TeaserFlags({ teaser }) {
    return (
        <>
            {teaser.isPlus ? <Badge tone="plus">Plus</Badge> : null}
            {teaser.genre === "ticker" ? <LiveBadge /> : null}
            {teaser.hasVideo ? <Badge tone="video"><Icon name="play" size={10} />Video</Badge> : null}
        </>
    );
}

function LiveBadge() {
    return (
        <Badge tone="live">
            <Text className="size-1.5 animate-pulse-live rounded-full bg-white" />
            Live
        </Badge>
    );
}

function CommentCount({ count, href }) {
    if (!count)
        return null;
    return (
        <Anchor href={`${href}#kommentare`} className="inline-flex items-center gap-1 text-xs text-ink-500 hover:text-brand-600" aria-label={`${count} Kommentare`}>
            <Icon name="comment" size={14} />
            {formatCount(count)}
        </Anchor>
    );
}

export function TeaserImage({ teaser, ratio = "16x9", sizes, className, priority }) {
    const picture = teaser.element?.picture;
    if (!picture)
        return null;
    return (
        <Box className={clsx("relative shrink-0 overflow-hidden rounded-teaser", className)}>
            <Picture picture={picture} ratio={ratio} sizes={sizes} priority={priority} imgClassName="transition-transform duration-300 group-hover/teaser:scale-[1.03]" />
            {teaser.hasVideo ? <PlayOverlay /> : null}
            <ImageCredit source={picture.source} />
        </Box>
    );
}

function PlayOverlay() {
    return (
        <Text className="absolute bottom-2 left-2 grid size-9 place-items-center rounded-full bg-ink-900/70 text-white backdrop-blur-sm">
            <Icon name="play" size={18} />
        </Text>
    );
}

function ImageCredit({ source }) {
    return <Text className="pointer-events-none absolute right-1 bottom-1 hidden rounded-sm bg-ink-900/50 px-1 text-[0.625rem] text-white/90 group-hover/teaser:block">{source}</Text>;
}

export function CategoryIcon({ icon }) {
    if (!icon)
        return null;
    const name = { video: "play", gallery: "gallery", live: "live", audio: "headphones" }[icon.type];
    return (
        <Text className="mr-1 inline-flex translate-y-0.5 text-brand-600" title={icon.label}>
            <Icon name={name} size={14} />
        </Text>
    );
}
