import { useCallback, useMemo, useRef, useState } from "react";
import dynamic from "next/dynamic";
import clsx from "clsx";
import { Icon } from "../ui/icons.jsx";
import { fetchJson } from "../../lib/data.js";
import { debounce } from "../../lib/debounce.js";

const SuggestionList = dynamic(() => import("./SuggestionList.jsx"), { ssr: false });

const LISTBOX_ID = "search-suggestions-listbox";

function suggestPath(query) {
    return `search/suggest/${encodeURIComponent(query.toLowerCase())}.json`;
}

export function SearchBox() {
    const inputRef = useRef(null);
    const [query, setQuery] = useState("");
    const [open, setOpen] = useState(false);
    const [result, setResult] = useState(null);
    const [active, setActive] = useState(-1);
    const latest = useRef("");

    const load = useMemo(() => debounce((value) => {
        latest.current = value;
        fetchJson(value ? suggestPath(value) : "search/zero-input.json").then((data) => {
            if (latest.current === value) {
                setResult(value ? { kind: "suggest", items: data.suggestions } : { kind: "zero", items: data.trending.map((text, i) => ({ text, id: `t${i}`, type: "trend" })) });
                setActive(-1);
            }
        });
    }, 150), []);

    const onFocus = useCallback(() => {
        setOpen(true);
        load(query);
    }, [load, query]);

    const onChange = useCallback((event) => {
        setQuery(event.target.value);
        setOpen(true);
        load(event.target.value);
    }, [load]);

    const close = useCallback(() => {
        setOpen(false);
        setActive(-1);
        inputRef.current?.blur();
    }, []);

    const onKeyDown = useCallback((event) => {
        const count = result?.items.length ?? 0;
        if (event.key === "ArrowDown") {
            event.preventDefault();
            setActive((value) => (count ? (value + 1) % count : -1));
        } else if (event.key === "ArrowUp") {
            event.preventDefault();
            setActive((value) => (count ? (value - 1 + count) % count : -1));
        } else if (event.key === "Escape") {
            close();
        }
    }, [result, close]);

    const showList = open && result && result.items.length > 0;
    return (
        <form role="search" action="suche/" className="relative w-full max-w-xl" onSubmit={(event) => event.preventDefault()}>
            <label htmlFor="portal-search" className="sr-only">Suche</label>
            <div className={clsx("flex h-11 items-center rounded-chip border bg-paper pr-1 pl-4 transition-colors", open ? "border-brand-500 ring-2 ring-brand-100" : "border-ink-300 hover:border-ink-400")}>
                <input
                    ref={inputRef}
                    id="portal-search"
                    type="search"
                    role="combobox"
                    autoComplete="off"
                    aria-autocomplete="list"
                    aria-expanded={showList ? "true" : "false"}
                    aria-controls={LISTBOX_ID}
                    aria-activedescendant={showList && active >= 0 ? `suggestion-${result.items[active].id}` : undefined}
                    placeholder="Suchbegriff eingeben"
                    value={query}
                    onFocus={onFocus}
                    onChange={onChange}
                    onKeyDown={onKeyDown}
                    className="h-full min-w-0 flex-1 bg-transparent text-base text-ink-900 outline-none placeholder:text-ink-400"
                />
                <button type="submit" aria-label="Suchen" className="grid size-9 cursor-pointer place-items-center rounded-full bg-brand-600 text-white hover:bg-brand-700">
                    <Icon name="search" size={18} />
                </button>
            </div>
            {showList ? <SuggestionList id={LISTBOX_ID} result={result} query={query} active={active} onPick={close} /> : null}
        </form>
    );
}
