// The tracking attributes every teaser and control carries, read by the
// first-party tracker and by third-party tags.
export function teaserTracking(teaser, stage) {
    return {
        "data-tracking": `${stage?.trackingName ?? "page"}|${teaser.trackingPosition}|${teaser.id}|${teaser.layout}${teaser.variant ? `-${teaser.variant}` : ""}`,
        "data-sctrack": `teaser:${teaser.id}`,
        "data-tb-region": stage?.trackingName ?? "page",
        "data-tb-region-item": teaser.trackingPosition,
        "data-tb-title": "",
        "data-tb-link": "",
    };
}

export function interactionTracking(name, position) {
    return { "data-interaction-element": name, "data-tracking": `ui|${name}${position ? `|${position}` : ""}` };
}
