import { forwardRef, useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import { Icon } from "./icons.jsx";
import { imageUrl, srcSet } from "../../lib/images.js";
import { formatRelative, formatTime } from "../../lib/format.js";
import { useNow } from "../contexts.jsx";
import { Anchor, Box, Item, Text } from "./ds.jsx";

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function VisuallyHidden({ children, as: Tag = "span" }) {
    return <Tag className="sr-only">{children}</Tag>;
}

const BUTTON_VARIANTS = {
    plain: "text-ink-700 hover:text-brand-600 dark:text-ink-200",
    outline: "rounded-chip border border-ink-300 px-3 py-1.5 text-sm font-medium text-ink-800 hover:border-brand-500 hover:text-brand-600",
    solid: "rounded-chip bg-brand-600 px-4 py-2 text-sm font-bold text-white hover:bg-brand-700 active:bg-brand-800",
    round: "grid size-10 place-items-center rounded-full border border-ink-200 bg-paper/90 text-ink-800 shadow-card hover:border-brand-400 hover:text-brand-600 disabled:opacity-40",
    chip: "rounded-chip bg-ink-100 px-3 py-1 text-xs font-medium text-ink-700 hover:bg-brand-50 hover:text-brand-700",
};

export const Button = forwardRef(function Button({ variant = "plain", className, children, ...props }, ref) {
    return (
        <button ref={ref} type="button" className={clsx("inline-flex cursor-pointer items-center gap-1.5 transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-500", BUTTON_VARIANTS[variant], className)} {...props}>
            {children}
        </button>
    );
});

export function Chevron({ open, className }) {
    return <Icon name="chevronDown" size={16} className={clsx("transition-transform duration-150", open && "rotate-180", className)} />;
}

// A popover anchored below its trigger, placed from the trigger's geometry
// and kept inside the viewport.
export function Popover({ anchorRef, open, onClose, labelledBy, className, align = "start", children }) {
    const ref = useRef(null);
    const [position, setPosition] = useState(null);

    useIsomorphicLayoutEffect(() => {
        if (!open || !anchorRef.current)
            return;
        const anchor = anchorRef.current.getBoundingClientRect();
        const panel = ref.current.getBoundingClientRect();
        const viewport = document.documentElement.clientWidth;
        let left = align === "end" ? anchor.right - panel.width : anchor.left;
        left = Math.max(8, Math.min(left, viewport - panel.width - 8));
        setPosition({ top: anchor.bottom + window.scrollY + 6, left: left + window.scrollX });
    }, [open, anchorRef, align]);

    useEffect(() => {
        if (!open)
            return;
        const onKey = (event) => {
            if (event.key === "Escape")
                onClose();
        };
        const onPointer = (event) => {
            if (!ref.current?.contains(event.target) && !anchorRef.current?.contains(event.target))
                onClose();
        };
        document.addEventListener("keydown", onKey);
        document.addEventListener("pointerdown", onPointer);
        return () => {
            document.removeEventListener("keydown", onKey);
            document.removeEventListener("pointerdown", onPointer);
        };
    }, [open, onClose, anchorRef]);

    if (!open)
        return null;
    return (
        <Box
            ref={ref}
            role="dialog"
            aria-labelledby={labelledBy}
            style={position ? { top: position.top, left: position.left } : { visibility: "hidden" }}
            className={clsx("absolute z-(--z-popover) min-w-64 animate-slide-down rounded-teaser border border-ink-200 bg-paper p-4 shadow-popover dark:border-ink-700", className)}
        >
            {children}
        </Box>
    );
}

export function useDisclosure(initial = false) {
    const [open, setOpen] = useState(initial);
    const toggle = useCallback(() => setOpen((value) => !value), []);
    const close = useCallback(() => setOpen(false), []);
    return { open, toggle, close, setOpen };
}

export function Picture({ picture, sizes = "(min-width: 1024px) 640px, 100vw", className, imgClassName, priority = false, ratio = "16x9" }) {
    const [desktop, mobile] = picture?.sources ?? [{ src: "" }, { src: "" }];
    const sets = useMemo(() => [srcSet(desktop.src), srcSet(mobile.src), imageUrl(desktop.src, 400)], [desktop.src, mobile.src]);
    if (!picture)
        return null;
    return (
        <picture className={clsx("relative block overflow-hidden bg-ink-100 dark:bg-ink-800", className)}>
            <source media={desktop.media} srcSet={sets[0]} sizes={sizes} width={desktop.width} height={desktop.height} />
            <source media={mobile.media} srcSet={sets[1]} sizes={sizes} width={mobile.width} height={mobile.height} />
            <img
                src={sets[2]}
                alt={picture.alt}
                width={desktop.width}
                height={desktop.height}
                loading={priority ? "eager" : "lazy"}
                fetchPriority={priority ? "high" : undefined}
                decoding="async"
                className={clsx("h-auto w-full object-cover", ratio === "1x1" ? "aspect-square" : ratio === "3x2" ? "aspect-[3/2]" : "aspect-video", imgClassName)}
            />
        </picture>
    );
}

export function Timestamp({ value, relative = true, className }) {
    const now = useNow();
    const label = useMemo(() => (relative ? formatRelative(value, now) : formatTime(value)), [value, now, relative]);
    const iso = useMemo(() => new Date(value).toISOString(), [value]);
    return (
        <time dateTime={iso} className={clsx("text-xs text-ink-500 tabular-nums", className)}>
            {label}
        </time>
    );
}

export function Divider({ className }) {
    return <hr className={clsx("my-4 border-0 border-t border-ink-200 dark:border-ink-700", className)} />;
}

export function Badge({ tone = "neutral", children, className }) {
    return (
        <Text className={clsx(
            "inline-flex items-center gap-1 rounded-sm px-1.5 py-0.5 text-2xs font-bold tracking-wide uppercase",
            tone === "live" && "bg-live-500 text-white",
            tone === "plus" && "bg-plus-500 text-white",
            tone === "video" && "bg-video-500 text-white",
            tone === "neutral" && "bg-ink-100 text-ink-700 dark:bg-ink-800 dark:text-ink-200",
            tone === "opinion" && "bg-signal-100 text-signal-700",
            className,
        )}>
            {children}
        </Text>
    );
}

export function LinkList({ links, className, itemClassName }) {
    return (
        <ul className={clsx("flex flex-col gap-1.5", className)}>
            {links.map((link) => (
                <Item key={link.href} className={itemClassName}>
                    <Anchor href={link.href} className="text-sm text-ink-700 transition-colors hover:text-brand-600 hover:underline dark:text-ink-200">{link.label}</Anchor>
                </Item>
            ))}
        </ul>
    );
}

export function useStableId(prefix) {
    return `${prefix}-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
}
