// The portal's word mark: a gradient badge with clipped lettering.
export function Logo({ id = "logo", className }) {
    return (
        <svg viewBox="0 0 168 40" width="168" height="40" role="img" aria-label="Nachrichtenportal" className={className}>
            <defs>
                <linearGradient id={`${id}-bg`} x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0" stopColor="#1d768d" />
                    <stop offset="0.55" stopColor="#145f74" />
                    <stop offset="1" stopColor="#0a2c36" />
                </linearGradient>
                <linearGradient id={`${id}-accent`} x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0" stopColor="#ffcb66" />
                    <stop offset="1" stopColor="#f2a100" />
                </linearGradient>
                <clipPath id={`${id}-clip`}>
                    <rect x="0" y="0" width="40" height="40" rx="8" />
                </clipPath>
            </defs>
            <g clipPath={`url(#${id}-clip)`}>
                <rect width="40" height="40" fill={`url(#${id}-bg)`} />
                <rect x="0" y="30" width="40" height="10" fill={`url(#${id}-accent)`} />
            </g>
            <path d="M10 26V10h4l8 10V10h4v16h-4l-8-10v10h-4Z" fill="#fff" />
            <text x="50" y="27" fontFamily="Roboto, Arial, sans-serif" fontWeight="700" fontSize="19" fill="currentColor">Nachrichten</text>
        </svg>
    );
}

export function SectionGlyph({ id, hue }) {
    return (
        <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" className="shrink-0">
            <defs>
                <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stopColor={`hsl(${hue} 45% 55%)`} />
                    <stop offset="1" stopColor={`hsl(${hue} 50% 35%)`} />
                </linearGradient>
            </defs>
            <rect width="16" height="16" rx="3" fill={`url(#${id})`} />
        </svg>
    );
}
