import { NOW } from "./clock.js";

const TIME_ZONE = "Europe/Berlin";
const timeFormat = new Intl.DateTimeFormat("de-DE", { hour: "2-digit", minute: "2-digit", timeZone: TIME_ZONE });
const dateFormat = new Intl.DateTimeFormat("de-DE", { day: "2-digit", month: "2-digit", year: "numeric", timeZone: TIME_ZONE });
const longDateFormat = new Intl.DateTimeFormat("de-DE", { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: TIME_ZONE });
const weekdayFormat = new Intl.DateTimeFormat("de-DE", { weekday: "short", timeZone: TIME_ZONE });
const relativeFormat = new Intl.RelativeTimeFormat("de-DE", { numeric: "auto" });
const numberFormat = new Intl.NumberFormat("de-DE", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
const percentFormat = new Intl.NumberFormat("de-DE", { style: "percent", maximumFractionDigits: 2, minimumFractionDigits: 2, signDisplay: "exceptZero" });
const countFormat = new Intl.NumberFormat("de-DE");

export function formatTime(timestamp) {
    return `${timeFormat.format(timestamp)} Uhr`;
}

export function formatDate(timestamp) {
    return dateFormat.format(timestamp);
}

export function formatLongDate(timestamp) {
    return longDateFormat.format(timestamp);
}

export function formatWeekday(timestamp) {
    return weekdayFormat.format(timestamp);
}

export function formatRelative(timestamp, reference = NOW) {
    const minutes = Math.round((timestamp - reference) / 60000);
    if (Math.abs(minutes) < 60)
        return relativeFormat.format(minutes, "minute");
    const hours = Math.round(minutes / 60);
    if (Math.abs(hours) < 24)
        return relativeFormat.format(hours, "hour");
    return formatDate(timestamp);
}

export function formatNumber(value) {
    return numberFormat.format(value);
}

export function formatPercent(value) {
    return percentFormat.format(value / 100);
}

export function formatCount(value) {
    return countFormat.format(value);
}
