import { useRef, useState } from "react";
import dynamic from "next/dynamic";
import clsx from "clsx";
import { Logo, Icon } from "../ui/icons.jsx";
import { Button, Chevron, Popover, useDisclosure, useStableId } from "../ui/primitives.jsx";
import { usePage } from "../contexts.jsx";
import { formatLongDate } from "../../lib/format.js";
import { NOW } from "../../lib/clock.js";
import { interactionTracking } from "../../lib/tracking.js";
import { SearchBox } from "./SearchBox.jsx";
import { Anchor, Box, Item, Text } from "../ui/ds.jsx";

const WeatherWidget = dynamic(() => import("./WeatherWidget.jsx"), { ssr: false, loading: () => <Text className="inline-block h-6 w-28 rounded-sm bg-ink-100" /> });
const MarketStrip = dynamic(() => import("./MarketStrip.jsx"), { ssr: false, loading: () => <Text className="inline-block h-4 w-80" /> });
const LoginOverlay = dynamic(() => import("./LoginOverlay.jsx"), { ssr: false });

function TopBar() {
    return (
        <Box className="border-b border-ink-200 bg-paper-muted text-xs text-ink-600 dark:border-ink-700 dark:bg-paper-raised">
            <Box className="mx-auto flex h-8 max-w-(--width-page) items-center gap-6 px-4">
                <Text>{formatLongDate(NOW)}</Text>
                <MarketStrip />
                <Box className="ml-auto">
                    <WeatherWidget />
                </Box>
            </Box>
        </Box>
    );
}

function LoginButton() {
    const [open, setOpen] = useState(false);
    return (
        <>
            <Button variant="outline" aria-label="E-Mail-Login" onClick={() => setOpen(true)} {...interactionTracking("login")}>
                <Icon name="mail" size={18} />
                E-Mail
            </Button>
            {open ? <LoginOverlay onClose={() => setOpen(false)} /> : null}
        </>
    );
}

function NavItem({ item }) {
    return (
        <Item className="group/nav relative">
            <Anchor href={item.href} className="flex h-11 items-center px-2.5 text-[0.9375rem] font-medium whitespace-nowrap text-white/90 transition-colors hover:bg-brand-700 hover:text-white group-focus-within/nav:bg-brand-700">
                {item.label}
            </Anchor>
            {item.dropdown.length ? (
                <Box className="invisible absolute top-full left-0 z-(--z-popover) min-w-52 rounded-b-teaser bg-paper py-2 opacity-0 shadow-popover transition-opacity group-focus-within/nav:visible group-focus-within/nav:opacity-100 group-hover/nav:visible group-hover/nav:opacity-100">
                    <ul>
                        {item.dropdown.map((link) => (
                            <Item key={link.href}>
                                <Anchor href={link.href} className="block px-4 py-1.5 text-sm text-ink-800 hover:bg-brand-50 hover:text-brand-700">{link.label}</Anchor>
                            </Item>
                        ))}
                    </ul>
                </Box>
            ) : null}
        </Item>
    );
}

function RegionMenu({ regions }) {
    const anchorRef = useRef(null);
    const { open, toggle, close } = useDisclosure();
    const id = useStableId("regions");
    return (
        <Item className="relative">
            <button ref={anchorRef} type="button" aria-expanded={open} aria-label="Regionen" onClick={toggle} className="flex h-11 cursor-pointer items-center gap-1 px-2.5 text-[0.9375rem] font-medium text-white/90 hover:bg-brand-700 hover:text-white" {...interactionTracking("region-menu")}>
                <Icon name="location" size={16} />
                Regionen
                <Chevron open={open} />
            </button>
            <Popover anchorRef={anchorRef} open={open} onClose={close} labelledBy={id} align="end" className="w-[36rem]">
                <h3 id={id} className="mb-3 text-xs font-bold text-ink-500 uppercase">Nachrichten aus Ihrer Region</h3>
                <ul className="grid grid-cols-4 gap-x-4 gap-y-1.5">
                    {regions.map((link) => (
                        <Item key={link.href}>
                            <Anchor href={link.href} className="flex items-center gap-1.5 text-sm text-ink-800 hover:text-brand-700">
                                <Icon name="location" size={12} className="text-ink-400" />
                                {link.label}
                            </Anchor>
                        </Item>
                    ))}
                </ul>
            </Popover>
        </Item>
    );
}

function NavigationBar({ navigation }) {
    return (
        <nav aria-label="Hauptnavigation" className="bg-brand-600 dark:bg-brand-800">
            <ul className="mx-auto flex max-w-(--width-page) items-stretch overflow-visible px-2">
                {navigation.items.slice(0, 14).map((item) => <NavItem key={item.href} item={item} />)}
                <MoreSections items={navigation.items.slice(14)} />
                <RegionMenu regions={navigation.regions} />
            </ul>
        </nav>
    );
}

function MoreSections({ items }) {
    return (
        <Item className="group/nav relative">
            <Text className="flex h-11 cursor-default items-center gap-1 px-2.5 text-[0.9375rem] font-medium text-white/90">
                Mehr
                <Icon name="chevronDown" size={14} />
            </Text>
            <Box className="invisible absolute top-full left-0 z-(--z-popover) min-w-48 bg-paper py-2 shadow-popover group-hover/nav:visible">
                <ul>
                    {items.map((item) => (
                        <Item key={item.href}><Anchor href={item.href} className="block px-4 py-1.5 text-sm text-ink-800 hover:bg-brand-50">{item.label}</Anchor></Item>
                    ))}
                </ul>
            </Box>
        </Item>
    );
}

export function Header() {
    const page = usePage();
    return (
        <header className="relative z-(--z-sticky-header) bg-paper shadow-card">
            <TopBar />
            <Box className="mx-auto flex h-18 max-w-(--width-page) items-center gap-6 px-4">
                <Anchor href="./" aria-label="Startseite" className="text-ink-900 dark:text-white">
                    <Logo id="logo-header" />
                </Anchor>
                <SearchBox />
                <Box className={clsx("ml-auto flex items-center gap-3")}>
                    <LoginButton />
                </Box>
            </Box>
            <NavigationBar navigation={page.navigation} />
        </header>
    );
}
