import clsx from "clsx";
import { CategoryIcon, Headline, TeaserFrame, TeaserImage, TeaserLink, TeaserMeta, TeaserText, TopLine } from "./parts.jsx";
import { Timestamp } from "../ui/primitives.jsx";
import { Box, Text } from "../ui/ds.jsx";

export function StreamSmall({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-row gap-4 border-t border-ink-200 pt-4 dark:border-ink-700">
            <TeaserImage teaser={teaser} ratio="3x2" sizes="200px" className="w-[calc(var(--width)_/_16_*_2rem)] max-w-50 basis-2/5" />
            <Box className="flex min-w-0 flex-1 flex-col">
                <Headline teaser={teaser} size="s" clamp={4} />
                <TeaserMeta teaser={teaser} />
            </Box>
        </TeaserFrame>
    );
}

export function StreamMedium({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-col gap-3 md:flex-row md:gap-5">
            <TeaserImage teaser={teaser} sizes="(min-width: 1024px) 400px, 100vw" className="md:w-1/2" />
            <Box className="flex min-w-0 flex-1 flex-col">
                <Headline teaser={teaser} size="m" clamp={3} />
                <TeaserText teaser={teaser} />
                <TeaserMeta teaser={teaser} />
            </Box>
        </TeaserFrame>
    );
}

export function StreamLarge({ teaser, priority }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-col gap-3">
            <TeaserImage teaser={teaser} priority={priority} sizes="(min-width: 1024px) 640px, 100vw" />
            <Headline teaser={teaser} size="l" />
            <TeaserText teaser={teaser} clamp={3} />
            <TeaserMeta teaser={teaser} />
        </TeaserFrame>
    );
}

export function StreamLargeCapsized({ teaser, priority }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-col overflow-hidden rounded-teaser bg-brand-900 text-white">
            <TeaserImage teaser={teaser} priority={priority} className="rounded-none" sizes="(min-width: 1024px) 640px, 100vw" />
            <Box className="p-4 [&_h3]:text-white [&_span]:text-brand-200">
                <Headline teaser={teaser} size="l" />
                <TeaserText teaser={teaser} className="text-brand-100" />
            </Box>
        </TeaserFrame>
    );
}

export function Card({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="h-full flex-col overflow-hidden rounded-teaser bg-paper shadow-card hover:shadow-popover dark:bg-paper-raised">
            <TeaserImage teaser={teaser} ratio="3x2" sizes="300px" className="rounded-none" />
            <Box className="flex flex-1 flex-col p-3">
                <Headline teaser={teaser} size="s" clamp={3} />
                <TeaserMeta teaser={teaser} className="mt-auto pt-2" />
            </Box>
        </TeaserFrame>
    );
}

export function Hero({ teaser, priority }) {
    return (
        <TeaserFrame teaser={teaser} className="h-full flex-col">
            <TeaserImage teaser={teaser} priority={priority} sizes="(min-width: 1024px) 640px, 100vw" className="rounded-b-none" />
            <Box className="flex flex-1 flex-col rounded-b-teaser bg-paper-muted p-4 dark:bg-paper-raised">
                <Headline teaser={teaser} size="l" clamp={3} />
                <TeaserText teaser={teaser} clamp={2} />
                <TeaserMeta teaser={teaser} className="mt-auto pt-3" />
            </Box>
        </TeaserFrame>
    );
}

export function Video({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="h-full flex-col">
            <TeaserImage teaser={{ ...teaser, hasVideo: true }} sizes="300px" />
            <Headline teaser={teaser} size="xs" clamp={3} className="mt-2" />
        </TeaserFrame>
    );
}

export function Companion({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-row items-start gap-3 py-2.5">
            <TeaserImage teaser={teaser} ratio="1x1" sizes="80px" className="w-20" />
            <Box className="min-w-0 flex-1">
                <Text className="text-xs font-medium text-brand-600">{teaser.topLine}</Text>
                <h4 className="line-clamp-3 text-sm leading-snug font-bold text-ink-900 group-hover/teaser:text-brand-700 dark:text-ink-50">
                    <TeaserLink teaser={teaser}>
                        <CategoryIcon icon={teaser.categoryIcon} />
                        {teaser.headline}
                    </TeaserLink>
                </h4>
            </Box>
        </TeaserFrame>
    );
}

export function HeadlineOnly({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} as="li" className="flex-row items-baseline gap-2 border-b border-ink-100 py-2 last:border-0 dark:border-ink-800">
            <Timestamp value={teaser.published} relative={false} className="w-16 shrink-0" />
            <h4 className="text-sm leading-snug font-medium text-ink-900 group-hover/teaser:text-brand-700 dark:text-ink-50">
                <TeaserLink teaser={teaser}>
                    <CategoryIcon icon={teaser.categoryIcon} />
                    {teaser.headline}
                </TeaserLink>
            </h4>
        </TeaserFrame>
    );
}

export function Portrait({ teaser }) {
    return (
        <TeaserFrame teaser={teaser} className="flex-col items-center gap-2 text-center">
            <TeaserImage teaser={teaser} ratio="1x1" sizes="120px" className="w-24 rounded-full" />
            <TopLine teaser={teaser} className="text-xs" />
            <h4 className="line-clamp-3 text-sm font-bold">
                <TeaserLink teaser={teaser}>{teaser.headlineShort}</TeaserLink>
            </h4>
        </TeaserFrame>
    );
}

const LAYOUTS = {
    "stream-small": StreamSmall,
    "stream-medium": StreamMedium,
    "stream-large": StreamLarge,
    "stream-large_capsized": StreamLargeCapsized,
    card: Card,
    hero: Hero,
    video: Video,
    companion: Companion,
    headline: HeadlineOnly,
    portrait: Portrait,
};

export function Teaser({ teaser, priority }) {
    const Layout = LAYOUTS[teaser.variant ? `${teaser.layout}-${teaser.variant}` : teaser.layout] ?? LAYOUTS[teaser.layout] ?? StreamSmall;
    return <Layout teaser={teaser} priority={priority} />;
}

export function TeaserList({ items, className }) {
    return (
        <Box className={clsx("flex flex-col gap-(--teaser-gap)", className)}>
            {items.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
        </Box>
    );
}
