// Layout and text primitives of the design system. Most host elements of the
// page render through one of these, each composing its class list once per
// change, as the reference's component library does.
import { useMemo } from "react";
import clsx from "clsx";

function useClassName(className, base) {
    return useMemo(() => clsx(base, className) || undefined, [className, base]);
}

export function Box({ as: Tag = "div", className, ref, ...props }) {
    return <Tag ref={ref} className={useClassName(className)} {...props} />;
}

export function Text({ as: Tag = "span", className, ref, ...props }) {
    return <Tag ref={ref} className={useClassName(className)} {...props} />;
}

export function Stack({ as: Tag = "div", gap = "gap-(--teaser-gap)", className, ...props }) {
    return <Tag className={useClassName(className, `flex flex-col ${gap}`)} {...props} />;
}

export function Cluster({ as: Tag = "div", className, ...props }) {
    return <Tag className={useClassName(className, "flex flex-wrap items-center")} {...props} />;
}

export function Grid({ as: Tag = "div", columns = "desk:grid-cols-2", className, ...props }) {
    return <Tag className={useClassName(className, `grid grid-cols-1 ${columns}`)} {...props} />;
}

export function Item({ as: Tag = "li", className, ...props }) {
    return <Tag className={useClassName(className)} {...props} />;
}

export function Anchor({ className, ref, ...props }) {
    return <a ref={ref} className={useClassName(className)} {...props} />;
}

export function Heading({ level = 2, className, ...props }) {
    const Tag = `h${level}`;
    return <Tag className={useClassName(className)} {...props} />;
}

export function Paragraph({ className, ...props }) {
    return <p className={useClassName(className)} {...props} />;
}
