// The site's small data hook: fetches JSON from the portal's API with a
// per-URL cache, as the reference's own hook does (no SWR or React Query).
import { useEffect, useState } from "react";

const cache = new Map();

export function apiUrl(path) {
    return `data/api/${path}`;
}

export function fetchJson(path) {
    const url = apiUrl(path);
    if (!cache.has(url))
        cache.set(url, fetch(url).then((response) => response.json()));
    return cache.get(url);
}

export function useApi(path) {
    const [state, setState] = useState({ data: null, loading: !!path, error: null });
    useEffect(() => {
        if (!path)
            return;
        let cancelled = false;
        setState((previous) => ({ ...previous, loading: true }));
        fetchJson(path).then(
            (data) => !cancelled && setState({ data, loading: false, error: null }),
            (error) => !cancelled && setState({ data: null, loading: false, error }),
        );
        return () => {
            cancelled = true;
        };
    }, [path]);
    return state;
}
