// A trailing debounce. In the benchmark frame the timer is replaced by the
// next task, so a step doesn't wait for wall-clock time but the call still
// runs after the input's own update, coalesced.
export function debounce(callback, delay) {
    let timer = null;
    let scheduled = false;
    let lastArgs = null;
    const debounced = (...args) => {
        lastArgs = args;
        const portal = window.__portal;
        if (portal?.hosted) {
            if (scheduled)
                return;
            scheduled = true;
            portal.afterTask(() => {
                scheduled = false;
                callback(...lastArgs);
            });
            return;
        }
        clearTimeout(timer);
        timer = setTimeout(() => callback(...lastArgs), delay);
    };
    debounced.cancel = () => clearTimeout(timer);
    return debounced;
}
