// Image URLs come from the image service as templates with a __WIDTH__
// placeholder; the page picks widths for srcset.
export const WIDTHS = [400, 800];

export function imageUrl(template, width) {
    return template.replace("__WIDTH__", String(width));
}

export function srcSet(template) {
    return WIDTHS.map((width) => `${imageUrl(template, width)} ${width}w`).join(", ");
}
